fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Create a new vector with the same length as the inputs
    let mut result = Vec::with_capacity(dst.len());
    
    // Iterate through all indices
    for i in 0..dst.len() {
        if mask[i] {
            // If mask is true, take element from src
            result.push(src[i]);
        } else {
            // If mask is false, take element from dst
            result.push(dst[i]);
        }
    }
    
    result
}